import json,re,glob,decimal,statistics
D=decimal.Decimal
def score(r):
 nums=re.findall(r'-?(?:\\d[\\d,]*(?:\\.\\d+)?|\\.\\d+)',r['output'])
 return bool(nums) and D(nums[-1].replace(',',''))==D(str(r['gts']).replace(',',''))
for typ in ['val_generations','rollouts']:
 for p in sorted(glob.glob('results/run60/'+typ+'/[0-9]*.jsonl'),key=lambda p:int(p.split('/')[-1].split('.')[0])):
  rows=[json.loads(l) for l in open(p)]; bad=[r for r in rows if score(r)"'!=bool(r['"'score'])]
  print(typ,p.split('/')[-1],len(rows),'logged',sum(r['score'] for r in rows)/len(rows),'numeric',sum(score(r) for r in rows)/len(rows),'mismatch',len(bad),'no####',sum('####' not in r['output'] for r in rows))
  if p.endswith('/60.jsonl'):
   for r in bad[:8]: print(' GOLD',r['gts'],'score',r['score'],'END',repr(r['output'][-220:]))
PY"

